 $audit=Sql "SELECT action,count(*) FROM audit_logs WHERE actor_user_id IN ('$adminId','$residentId','$disabledId') OR details_json->>'subjectHash' IN ('$adminSubject','$residentSubject','$disabledSubject','$unknownSubject','$throttleSubject') GROUP BY action ORDER BY action;"
 "CSRF=$csrfCode NO_CSRF=$noCsrf UNKNOWN=$unknown DISABLED=$disabled THROTTLE=$($throttleResults -join ',') LOGIN=$login ROTATED=$($before-ne$after) ME=$me BAD_CSRF=$badLogout RESIDENT_LOGIN=$residentLogin RESIDENT_ME=$residentMe LOGOUT=$logout AFTER_LOGOUT=$afterLogout RELOGIN=$relogin DEACTIVATED_SESSION=$deactivatedSession ROLE_CHANGED_SESSION=$roleChangedSession";'AUDIT:';$audit
